begin;
-- Phase 18 added exercises.tracking_type with a 'weight_reps' default and never backfilled the
-- shared catalogue, so the database believed every lift was measured in weight and reps while
-- the app knew better. validate_set_measurements then refused a push-up for having no weight —
-- and because a session's sets upsert in one statement, a single bodyweight exercise failed the
-- whole workout with a 23514, which the sync queue classes as permanent. Sessions containing any
-- of 45 catalogue exercises were therefore never stored at all.
--
-- These statements are generated from the app's own rule (src/modules/workout/trackingTypes.ts
-- over catalog.json); a test asserts the two still agree, so they cannot drift apart again.
-- Scoped to owner_user_id is null: an exercise a user created already carries its own answer.
update public.exercises set tracking_type = 'bodyweight_reps' where owner_user_id is null and id in (
  '10000000-0000-4000-8000-000000000016', '10000000-0000-4000-8000-000000000017', '10000000-0000-4000-8000-000000000018',
  '10000000-0000-4000-8000-000000000019', '10000000-0000-4000-8000-000000000029', '10000000-0000-4000-8000-000000000036',
  '10000000-0000-4000-8000-000000000037', '10000000-0000-4000-8000-000000000038', '10000000-0000-4000-8000-000000000039',
  '10000000-0000-4000-8000-000000000056', '10000000-0000-4000-8000-000000000074', '10000000-0000-4000-8000-000000000075',
  '10000000-0000-4000-8000-000000000100', '10000000-0000-4000-8000-000000000112', '10000000-0000-4000-8000-000000000113',
  '10000000-0000-4000-8000-000000000114', '10000000-0000-4000-8000-000000000115', '10000000-0000-4000-8000-000000000116',
  '10000000-0000-4000-8000-000000000128', '10000000-0000-4000-8000-000000000132', '10000000-0000-4000-8000-000000000133',
  '10000000-0000-4000-8000-000000000134', '10000000-0000-4000-8000-000000000142', '10000000-0000-4000-8000-000000000168',
  '10000000-0000-4000-8000-000000000169', '10000000-0000-4000-8000-000000000190', '10000000-0000-4000-8000-000000000202',
  '10000000-0000-4000-8000-000000000203', '10000000-0000-4000-8000-000000000204', '10000000-0000-4000-8000-000000000207',
  '10000000-0000-4000-8000-000000000208', '10000000-0000-4000-8000-000000000209', '10000000-0000-4000-8000-000000000218',
  '10000000-0000-4000-8000-000000000219', '10000000-0000-4000-8000-000000000220', '10000000-0000-4000-8000-000000000221',
  '10000000-0000-4000-8000-000000000223', '10000000-0000-4000-8000-000000000232'
);

update public.exercises set tracking_type = 'distance_duration' where owner_user_id is null and id in (
  '10000000-0000-4000-8000-000000000176', '10000000-0000-4000-8000-000000000177', '10000000-0000-4000-8000-000000000214'
